def _handle_lifecycle(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method == "GET":
        return _handle_lifecycle_get(environ, raw_id, start_response)
    if method == "POST":
        return _handle_lifecycle_post(environ, raw_id, start_response)
    return _error(
        start_response,
        "405 Method Not Allowed",
        "method_not_allowed",
        f"Method {method} is not allowed for this path.",
        allowed="GET, POST",
    )


def _handle_lifecycle_summary(
    method: str,
    environ: dict[str, Any],
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    # The summary is read-only: a declared non-empty (or malformed) body is
    # a bad request without consulting any business data. An omitted header
    # and an explicit zero length are accepted as an empty body.
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    # No filtering or pagination parameters whatsoever are accepted.
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    # Computed on the fly from the current registry: one record per
    # registered resource in resource registration order, each with the
    # same three keys in the same order as the per-resource lifecycle read
    # (id, state, reason). A resource that never left the default state is
    # reported as staged with a null reason without materializing a record;
    # a read must therefore never store anything. Nothing is reordered,
    # each resource appears exactly once, and an empty registry is a valid
    # empty array.
    records: list[dict[str, object]] = []
    for resource in store.list_all():
        record = lifecycle_store.get(resource.id)
        records.append(
            {"id": resource.id, "state": record.state, "reason": record.reason}
        )
    return _json_response(
        start_response,
        "200 OK",
        records,
        trailing_newline=True,
    )


def _handle_release_blockers(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    return _json_response(
        start_response,
        "200 OK",
        _promotion_blocker_report(raw_id),
        trailing_newline=True,
    )


def _promotion_blocker_report(resource_id: str) -> dict[str, object]:
    """Build one promotion-blocker record for ``resource_id``.

    Shared by the per-resource release-blocker view and the global
    promotion/blockers summary so both answers always come from the very
    same promotion checks as the staged -> released transition, without
    short-circuiting: both reason codes and every blocked dependency are
    reported. Read-only and computed on the fly; nothing is recorded.

    # Per-resource dependency closure size summary; the handler
    # answers the 405 (Allow: GET) for every other method.
    return _handle_dependency_closure_summary(
        method, environ, start_response
    )

